WITH matched_keys AS (SELECT store_id, id FROM inventory EXCEPT ALL SELECT store_id, id FROM inventory WHERE product_id IN (2, 3, 6, 9)), verified AS (SELECT s.* FROM inventory s INNER JOIN matched_keys k ON s.store_id = k.store_id AND s.id = k.id) SELECT DATE_TRUNC('MONTH', last_restock) AS activity_month, BIT_OR(quantity) AS quantity_bit_or, SUM(quantity) AS total_quantity, AVG(quantity) AS avg_quantity FROM verified GROUP BY activity_month ORDER BY avg_quantity ASC;
